#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"

/* Include the Exo-generated kernel header. */
#include "generated/atax/atax.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
      x[i] = 1 + (i / fn);
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline ATAX kernel: y = A^T * (A * x)
@proc
def kernel_atax_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # 1) Initialize y to zero
    for j in seq(0, n):
        y[j] = 0.0

    # 2) Initialize tmp to zero
    for i in seq(0, m):
        tmp[i] = 0.0

    # 3) tmp = A * x    (matrix-vector product over rows of A)
    for i in seq(0, m):
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

    # 4) y = A^T * tmp  (matrix-vector product over columns of A)
    for j in seq(0, n):
        for i in seq(0, m):
            y[j] += A[i, j] * tmp[i]


# ---------------------------------------------------------------------------
# Scheduling for performance
#
# Goals:
# - Improve reuse of x[] in tmp = A * x by tiling the j-dimension.
# - Parallelize the outer i-loop of tmp = A * x (no loop-carried dependencies).
# - Reorder the y = A^T * tmp loops to iterate over rows of A in the inner loop
#   for better spatial locality (row-major layout).
# - Keep the algorithm mathematically equivalent to y = A^T * (A * x).
# ---------------------------------------------------------------------------

kernel_atax = kernel_atax_base

# Tile size for the j-dimension in the tmp = A * x phase.
tile_j = 64

# 3a) Tile the inner j-loop of tmp = A * x:
#     for i in 0..m:
#       for j in 0..n:
#         tmp[i] += A[i,j] * x[j]
#
# We split j into (jo, ji) with a block size of tile_j, and use "cut_and_guard"
# so that arbitrary n are handled correctly via a guard on the last block.
tmp_j_loop = kernel_atax.find_loop("j #1")  # second 'j' loop: inner j of tmp = A * x
kernel_atax = divide_loop(kernel_atax, tmp_j_loop, tile_j, ("jo", "ji"),
                          tail="cut_and_guard")

# 3b) Parallelize the outer i-loop of tmp = A * x.
# Each iteration writes to a distinct tmp[i] and only reads A and x,
# so there are no cross-iteration dependencies.
tmp_i_loop = kernel_atax.find_loop("i #1")  # outer i of tmp = A * x
kernel_atax = parallelize_loop(kernel_atax, tmp_i_loop)

# 4a) Reorder the y = A^T * tmp loops:
#     Original (in kernel_atax_base): for j in 0..n: for i in 0..m: ...
#     After reordering:               for i in 0..m: for j in 0..n: ...
#
# This gives us contiguous row-wise access to A[i, j] in the inner loop,
# which is more cache-friendly on a row-major machine.
y_outer_j = kernel_atax.find_loop("j #1")  # outer j-loop of y = A^T * tmp
kernel_atax = reorder_loops(kernel_ataax, y_outer_j)

# Clean up algebra and remove any trivial loops/conditions introduced
# by tiling and reordering.
kernel_atax = simplify(kernel_atax)

# Rename the scheduled kernel to the symbol that the C driver expects.
kernel_atax = rename(kernel_atax, "kernel_atax")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_atax (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(x),
               (DATA_TYPE*)POLYBENCH_ARRAY(y),
               (DATA_TYPE*)POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
